Assert.equal(num, 8);
const sizes = [];
for (let i = 0; i < num; i++) {
  let [size] = dbView.cellTextForColumn(i, "sizeCol").split(" ");
  // The numbers in the UI are formatted per local regional settings.
  // E.g. 10.2 may be 10,2. Convert to dot before proceeding.
  size = size.replace(",", ".");
  sizes.push(Number(size));
}
return sizes.every(
  (value, index, array) =>
    index == 0 ||
    (ascending ? value >= array[index - 1] : value <= array[index - 1])
);

Assert.ok(checkSort(false));

dbView.sort(Ci.nsMsgViewSortType.bySize, Ci.nsMsgViewSortOrder.ascending);
Assert.ok(checkSort(true));

dbView.sort(Ci.nsMsgViewSortType.bySize, Ci.nsMsgViewSortOrder.descending);
Assert.ok(checkSort(false));
